//  2024-05-08 - 0.4 - J.SHI     - jira RAV-8497/8529 fix rst release doa/dob changed
//  2024-04-28 - 0.3 - J.SHI     - jira RAV-8329 add 0.5ns latency to avoid sw simulation fail
//  2024-04-24 - 0.2 - J.SHI     - Add ECC INJ and fix async rst async rls
//  2023-10-20 - 0.11- GS.JI     - Add Tag Anotation.
//  2023-08-28 - 0.1 - Yuan.Wang - Add internal redundant test input/output port from PH1P_PHY_ERAM.v.
//
///////////////////////////////////////////////////////////////////////////////

`timescale 1ps / 1ps

module PH1P_PHY_ERAM_V2 (
  dia, 
  dia_extra, 
  csa,
  addra, 
  ocea, 
  clka, 
  wea,
  orsta, 
  dib, 
  dib_extra, 
  csb,
  addrb, 
  oceb, 
  clkb, 
  web,
  orstb, 
  doa,
  doa_extra,
  dob,
  dob_extra,
  ecc_sbiterr,
  ecc_dbiterr,
  ecc_sbiterrinj,
  ecc_dbiterrinj,
//  fifoctrl_fifoen,// fifoctrl_* comes from fifoctrl hard module, just for simulation, no need customer/SW to connection
  fifoctrl_waddr,//following 4 signs just for simulation, no need connection
  fifoctrl_raddr,// 
  fifoctrl_we,   //
  fifoctrl_re,    //
  addra_casin, // cascade addra in
  addrb_casin, // cascade addrb in
  addra_casout, // cascade addra out
  addrb_casout,  // cascade addra out
  pib_rst_redmeet_n, // input for internal test, default 1
  probe_redmeet_pa, // output for test port A
  probe_redmeet_pb // output for test port B
);

output  [15:0] doa;
output  [15:0] dob;
output  [3:0] doa_extra;
output  [3:0] dob_extra;

input   [15:0] dia;         //              DEFAULT := "1111111111111111" 
input   [15:0] dib;         //              DEFAULT := "1111111111111111"
input   [3:0] dia_extra;    //              DEFAULT := "1111"
input   [3:0] dib_extra;    //              DEFAULT := "1111"
input   [2:0] csa;          //              DEFAULT := "010"
input   [2:0] csb;          //              DEFAULT := "010"
input   ocea;               //              DEFAULT := '1'
input   clka;               // [tag:clk]    DEFAULT := '0'
input   wea;                //              DEFAULT := '1'
input   orsta;              //              DEFAULT := '1'
input   oceb;               //              DEFAULT := '1'
input   clkb;               // [tag:clk]    DEFAULT := '0'
input   web;                //              DEFAULT := '1'
input   orstb;              //              DEFAULT := '1'
input   [13:0] addra;       //              DEFAULT := "11111111111111"
// 10/20 WWIDTH addra[3:0] -> byteena[3:0]
input   [13:0] addrb;       //              DEFAULT := "11111111111111"
// 10/20 RWIDTH addrb[1:0] -> byteenb[1:0]
output  ecc_sbiterr;
output  ecc_dbiterr; 
// fifo interface
input   [13:0] fifoctrl_waddr;  // [tag: hardwire]    DEFAULT := "11111111111111"
input   [13:0] fifoctrl_raddr;  // [tag: hardwire]    DEFAULT := "11111111111111"
input   fifoctrl_we;            // [tag: hardwire]    DEFAULT := '0'  
input   fifoctrl_re;            // [tag: hardwire]    DEFAULT := '0'
//input   fifoctrl_fifoen;      //                    DEFAULT := '0'
input   [13:0] addra_casin;     // [tag: hardwire]    DEFAULT := "00000000000000"
input   [13:0] addrb_casin;     // [tag: hardwire]    DEFAULT := "00000000000000"
output  [13:0] addra_casout;    // [tag: hardwire]
output  [13:0] addrb_casout;    // [tag: hardwire]
input   ecc_sbiterrinj;
input   ecc_dbiterrinj;
tri1 	[15:0] dia;
tri1 	[15:0] dib;
tri1    [3:0] dia_extra;
tri1    [3:0] dib_extra; 
tri1 	[13:0] addra;
tri1 	[13:0] addrb;
  
input  pib_rst_redmeet_n; // input for internal test, default 1
output  probe_redmeet_pa; // output for test port A
output  probe_redmeet_pb; // output for test port B
tri1 pib_rst_redmeet_n ;
wire probe_redmeet_pa = 1'b0;
wire probe_redmeet_pb = 1'b0;
//tri0    fifoctrl_fifoen;
// for ECC mode, MODE must be PDP20K
// PDP20K means Write or Read Port is 40bit mode, when PDP20K, 
// one of DATA_WIDTH_A or DATA_WIDTH_B must be 40
// for example : if 10 bit write & 40 bit read must follow:
// MODE="DPD20K",DATA_WIDTH_A="10",DATA_WIDTH_B="40"
parameter MODE = "DP20K";               // "DP20K", "FIFO20K"
parameter FIFOMODE = "DISABLE";         // "DISABLE", "ENABLE"
parameter DATA_WIDTH_A = "20";          // "1", "2", "5", "10", "20", "40"
parameter DATA_WIDTH_B = "20";          // "1", "2", "5", "10", "20", "40"
parameter CLKMODE = "ASYNC";            // "ASYNC","SYNC" 
parameter READBACK = "DISABLE";         // "DISABLE","ENABLE"
parameter DEVICE = "PHONEX";
parameter SPEEDLEVEL ="1";
parameter REGMODE_A = "NOREG";          // "NOREG", "OUTREG"
parameter REGMODE_B = "NOREG";          // "NOREG", "OUTREG"
parameter WRITEMODE_A = "NORMAL";       // "NORMAL", "READBEFOREWRITE", "WRITETHROUGH" 
parameter WRITEMODE_B = "NORMAL";       // "NORMAL", "READBEFOREWRITE", "WRITETHROUGH" 
parameter GSR = "ENABLE";               // "DISABLE", "ENABLE"
parameter OREGSET_A = "SET";            // "SET", "RESET"
parameter OREGSET_B = "SET";            // "SET", "RESET"
parameter ASYNC_RESET_RELEASE_A = "SYNC";  // "SYNC", "ASYNC"
parameter ASYNC_RESET_RELEASE_B = "SYNC";  // "SYNC", "ASYNC"
parameter RESETMODE_A = "ASYNC";          // "ASYNC", "SYNC"
parameter RESETMODE_B = "ASYNC";          // "ASYNC", "SYNC"
parameter SSROVERCE = "DISABLE";  //"DISABLE","ENABLE"
parameter ECC_DECODE = "DISABLE"; // "DISABLE","ENABLE"
parameter ECC_ENCODE = "DISABLE"; // "DISABLE","ENABLE" 
parameter OCEAMUX = "SIG"; //"0", "1", "INV", "SIG" 
parameter OCEBMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter RSTAMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter RSTBMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter CLKAMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter CLKBMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter WEAMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter WEBMUX = "SIG"; //"0", "1", "INV", "SIG"
parameter CSA0 = "SIG" ;  //"0","1","SIG"
parameter CSA1 = "SIG" ;  //"0","1","SIG","INV"
parameter CSA2 = "SIG" ;  //"0","1","SIG","INV"
parameter CSB0 = "SIG" ;  //"0","1","SIG"
parameter CSB1 = "SIG" ;  //"0","1","SIG","INV"
parameter CSB2 = "SIG" ;  //"0","1","SIG","INV"
parameter LADDRCAS_A = "NORMAL";//"NORMAL","CASFB","FIFO" 
parameter LADDRCAS_B = "NORMAL";//"NORMAL","CASFB","FIFO"
parameter HADDRCAS_A = "NORMAL";//"NORMAL","CASFB","FIFO"
parameter HADDRCAS_B = "NORMAL";//"NORMAL","CASFB","FIFO"
parameter INIT_ENABLE=1; 
`define ERAM_LATCHNORSTINOREG

parameter INIT_FILE = "";
